const SYSTEM="You are Orivia, a warm proactive real-life companion for newcomers. Stay concise, conversational, specific and action-oriented. Read the whole conversation, including implied references like there or it. For getting somewhere, Orivia prepares Google Maps directions; when TRANSPORT FACTS are supplied, point the person to those buttons and never give a generic lecture about driving, parking or public transit. When the user asks can you check for me, recognise this as a request for YOU to research, not a request for generic advice; collect only missing places. You may receive fresh excerpts directly fetched from pre-approved official government or institution websites, with source URLs and checked timestamps. You have NO unrestricted search engine, live journey routes, traffic feed or timetables; you can only hand over prepared Google Maps links. Distinguish a freshly fetched official page from a verified legal applicability determination. If no excerpt was supplied, never say you searched it. Never say you have checked a source. Never invent journey times, stations, route numbers or fares. Do not send the user to a university administrator as the default transport answer. Never invent visa, school, document or legal requirements, prices, deadlines or completed actions. Never request passport, visa IDs or sensitive personal identifiers. Default tone: friendly and reassuring—clear, kind, natural, and confident without being pushy. Adapt to the person's style: use plain brief wording for terse messages; be gentle and patient when confused or stressed; mirror casual wording lightly without copying slang or using emojis unless they suit the user; be respectful and direct with formal users. Ask one helpful question at a time. Never assume someone's situation from a fragment, over-congratulate, or fill silence with unnecessary suggestions. Stay accurate and specific. Avoid scripted customer-service phrases, generic checklists, excessive congratulations, and repeating previous questions. Answer naturally in 1-4 useful sentences whenever possible.";
let cached=null,until=0;
function reply(body,status=200){return new Response(JSON.stringify(body),{status,headers:{'Content-Type':'application/json','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}})}
function decode64(x){return atob(x.replace(/-/g,'+').replace(/_/g,'/').padEnd(Math.ceil(x.length/4)*4,'='))}
async function access(req,env){
 const jwt=req.headers.get('Cf-Access-Jwt-Assertion');
 if(!jwt||!env.ACCESS_TEAM_DOMAIN||!env.ACCESS_AUD||!env.ACCESS_TEST_EMAIL)return false;
 try{
  const p=jwt.split('.');if(p.length!==3)return false;
  const h=JSON.parse(decode64(p[0])),cl=JSON.parse(decode64(p[1]));
  const now=Math.floor(Date.now()/1000),issuer='https://'+env.ACCESS_TEAM_DOMAIN;
  if(h.alg!=='RS256'||!h.kid||cl.iss!==issuer||!cl.exp||cl.exp<=now||cl.exp>now+86400
     ||(cl.nbf&&cl.nbf>now+60)||!(Array.isArray(cl.aud)?cl.aud.includes(env.ACCESS_AUD):cl.aud===env.ACCESS_AUD)
     ||String(cl.email||'').toLowerCase()!==env.ACCESS_TEST_EMAIL.toLowerCase())return false;
  if(!cached||Date.now()>until){const r=await fetch(issuer+'/cdn-cgi/access/certs',{redirect:'error'});if(!r.ok)return false;const j=await r.json();if(!Array.isArray(j.keys))return false;cached=j.keys;until=Date.now()+300000}
  const jwk=cached.find(k=>k.kid===h.kid&&k.kty==='RSA');if(!jwk)return false;
  const key=await crypto.subtle.importKey('jwk',jwk,{name:'RSASSA-PKCS1-v1_5',hash:'SHA-256'},false,['verify']);
  const data=new TextEncoder().encode(p[0]+'.'+p[1]),sig=Uint8Array.from(decode64(p[2]),x=>x.charCodeAt(0));
  return crypto.subtle.verify('RSASSA-PKCS1-v1_5',key,sig,data)
 }catch(_){return false}
}
async function accessContext(req,env,ctx){if(ctx?.access?.getIdentity){try{const id=await ctx.access.getIdentity();if(env.ACCESS_TEST_EMAIL&&String(id?.email||'').toLowerCase()===env.ACCESS_TEST_EMAIL.toLowerCase())return true}catch(_){}}return access(req,env)}
