function toneLine(prefs){return TONES[prefs&&typeof prefs==='object'?prefs.style:'']||''}
function profileLine(prefs){
 const p=prefs&&typeof prefs==='object'?prefs.profile:null;if(!p||typeof p!=='object')return '';
 const clean=v=>typeof v==='string'?v.replace(/[\r\n<>{}]/g,' ').replace(/\s+/g,' ').trim().slice(0,60):'';
 const parts=[['Lives in',clean(p.city)],['Moving to',clean(p.movingTo)],['Here to',clean(p.who)],['Institution or workplace (as typed, not verified)',clean(p.place)]].filter(x=>x[1]).map(x=>x[0]+': '+x[1]);
 return parts.length?'\nThe user chose to share this About me information (user-provided, unverified; use it to avoid asking again, never repeat it back unprompted): '+parts.join('; ')+'.':'';
}
