async function personAllowance(req,env){
 if(!betaTable){await env.BUDGET_DB.prepare('CREATE TABLE IF NOT EXISTS beta_usage (day TEXT NOT NULL, who TEXT NOT NULL, calls INTEGER NOT NULL, PRIMARY KEY (day, who))').run();betaTable=true}
 const day=new Date().toISOString().slice(0,10),cap=Math.max(1,Math.min(200,Number(env.PERSON_DAILY_CAP)||25));
 const row=await env.BUDGET_DB.prepare('INSERT INTO beta_usage (day,who,calls) VALUES (?,?,1) ON CONFLICT(day,who) DO UPDATE SET calls=calls+1 WHERE calls < ? RETURNING calls').bind(day,await personKey(req,env),cap).first();
 if(Math.random()<0.02)await env.BUDGET_DB.prepare('DELETE FROM beta_usage WHERE day < ?').bind(day).run(); // keep only today
 return !!row;
}
